To solve this problem, we need to remove any inactive nodes from a Category tree. The tree structure is such that each node can have multiple children, and each node has a parent except the root node. The goal is to remove all inactive nodes and adjust the tree structure to maintain the hierarchy of active nodes.

### Approach
The approach involves three main steps:
1. **Traverse the Tree**: Collect all inactive nodes and their depths using a pre-order traversal.
2. **Sort Nodes by Depth**: Sort the collected inactive nodes in descending order of their depth. This ensures that deeper nodes (those farther from the root) are processed first, preventing issues with modifying the tree structure dynamically.
3. **Process Inactive Nodes**: For each inactive node, remove it from its parent's children list and promote its children to become children of its parent. This maintains the tree structure by moving active subtrees up one level.

### Solution Code
```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

protected int removeUnusedNodes() {
    List<Category> inactiveNodes = new ArrayList<>();
    Map<Category, Integer> nodeDepths = new HashMap<>();

    // Traverse the tree to collect inactive nodes and their depths
    traverseTree(root, 0, inactiveNodes, nodeDepths);

    // Sort the inactive nodes by depth in descending order to process deepest nodes first
    inactiveNodes.sort((a, b) -> Integer.compare(nodeDepths.get(b), nodeDepths.get(a)));

    int count = 0;
    for (Category node : inactiveNodes) {
        Category parent = node.getParent();
        if (parent != null) {
            // Remove the node from its parent's children list
            parent.getChildren().remove(node);

            // Get the node's children and add them to the parent's children list
            List<Category> children = node.getChildren();
            parent.getChildren().addAll(children);

            // Update the parent of each child to the current node's parent
            for (Category child : children) {
                child.setParent(parent);
            }

            count++;
        }
        // If parent is null (root node), do nothing as we cannot remove the root
    }

    return count;
}

private void traverseTree(Category node, int currentDepth, List<Category> inactiveNodes, Map<Category, Integer> nodeDepths) {
    if (node == null) {
        return;
    }

    // Check if the current node is inactive
    if (!node.isActive()) {
        inactiveNodes.add(node);
        nodeDepths.put(node, currentDepth);
    }

    // Recursively traverse all children
    for (Category child : node.getChildren()) {
        traverseTree(child, currentDepth + 1, inactiveNodes, nodeDepths);
    }
}
