            for (String s : split) {
                components.add(s);
            }
        }

        String[] relSplit = relativePath.split("/+");
        for (String part : relSplit) {
            if (part.isEmpty()) {
                continue;
            }
            if (part.equals(".")) {
                continue;
            } else if (part.equals("..")) {
                if (isAbsolute) {
                    if (components.size() > 1) {
                        components.remove(components.size() - 1);
                    }
                } else {
                    if (!components.isEmpty() && !components.get(components.size() - 1).equals("..")) {
